// @generated by `cargo xtask gen-contracts` from contracts/. Do not edit.

//! Every valid fixture in `contracts/fixtures` deserializes into its generated type and
//! serializes back to the same JSON (numbers compared as f64). Invalid fixtures are checked
//! against the full schema by `cargo xtask contracts`.

use serde::{Serialize, de::DeserializeOwned};
use serde_json::Value;

fn normalize(v: Value) -> Value {
    match v {
        Value::Number(n) => n.as_f64().map_or(Value::Null, |f| serde_json::json!(f)),
        Value::Array(a) => Value::Array(a.into_iter().map(normalize).collect()),
        Value::Object(o) => Value::Object(o.into_iter().map(|(k, v)| (k, normalize(v))).collect()),
        other => other,
    }
}

fn roundtrip<T: Serialize + DeserializeOwned>(rel: &str) {
    let path = format!(
        "{}/../../contracts/fixtures/{rel}",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path).expect("fixture is readable");
    let value: Value = serde_json::from_str(&text).expect("fixture is JSON");
    let typed: T = serde_json::from_value(value.clone()).unwrap_or_else(|e| panic!("{rel}: {e}"));
    let back = serde_json::to_value(&typed).expect("type serializes");
    assert_eq!(
        normalize(back),
        normalize(value),
        "{rel} does not round-trip"
    );
}

